+    generation: u64,
+    sequence: u64,
+}
+struct AudioSlot {
+    generation: u64,
+    audio: Option<Vec<u8>>,
+}
+struct AudioQueue {
+    next: u64,
+    emit: u64,
+    slots: BTreeMap<u64, AudioSlot>,
+}
+impl AudioQueue {
+    fn new() -> Self {
+        Self {
+            next: 0,
+            emit: 0,
+            slots: BTreeMap::new(),
+        }
+    }
+    fn reserve(&mut self, generation: u64) -> u64 {
+        let sequence = self.next;
+        self.next += 1;
+        self.slots.insert(
+            sequence,
+            AudioSlot {
+                generation,
+                audio: None,
+            },
+        );
