+                if !audio.is_empty() {
+                    ready.push(Event::Audio {
+                        audio,
+                        generation: slot.generation,
+                        sequence: self.emit,
+                    });
+                }
+            }
+            self.emit += 1;
+        }
+        ready
+    }
+    fn clear(&mut self) {
+        self.slots.clear();
+        self.emit = self.next;
+    }
